package in.foodcart.config; import in.foodcart.data.*; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*; import java.math.BigDecimal;
@Configuration @org.springframework.context.annotation.Profile("local") public class SeedData {@Bean @org.springframework.core.annotation.Order(1) CommandLineRunner seed(VendorRepository vendors,MenuCategoryRepository cats,MenuItemRepository items){return x->{if(vendors.findBySlug("raju-momos").isPresent()){items.findAll().forEach(i->{if(i.halfPrice==null&&("Veg Momos".equals(i.name)||"Chicken Momos".equals(i.name)||"Paneer Roll".equals(i.name))){i.halfPrice=i.price.divide(new BigDecimal("2"));items.save(i);}});return;}VendorEntity v=new VendorEntity();v.name="Raju Momos";v.slug="raju-momos";v.mobile="9999999999";v.description="Hand-folded momos and street-food favourites";v.address="Outside City Mall, Sector 18";v=vendors.save(v);String[] names={"Momos","Rolls","Drinks"};for(int n=0;n<3;n++){MenuCategoryEntity c=new MenuCategoryEntity();c.vendorId=v.id;c.name=names[n];c.sortOrder=n;cats.save(c);}for(Object[] d:new Object[][]{{"Veg Momos","80",true},{"Chicken Momos","110",true},{"Paneer Momos","100",false},{"Egg Roll","70",true},{"Paneer Roll","90",true},{"Cold Coffee","70",true}}){MenuItemEntity i=new MenuItemEntity();i.vendorId=v.id;i.name=(String)d[0];i.price=new BigDecimal((String)d[1]);i.available=(Boolean)d[2];if(i.name.equals("Veg Momos")||i.name.equals("Chicken Momos")||i.name.equals("Paneer Roll"))i.halfPrice=i.price.divide(new BigDecimal("2"));items.save(i);}};}}
